skin:
#s100 .stage{background:#050505;color:#39FF14;font-family:var(--mono)}
#s100 .stage::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(0deg,#ff00f50a 0 2px,transparent 2px 4px);pointer-events:none}
#s100 .d-nav{background:#111;border:2px dashed #FF00F5;border-radius:0;transform:rotate(-.6deg)}
#s100 .d-logo{font-weight:700;color:#00FFF3;text-shadow:2px 2px #FF00F5,-2px -2px #39FF14}
#s100 .d-links span{color:#ff86f2;opacity:.8}#s100 .d-links span:hover{opacity:1;text-decoration:underline wavy #39FF14}
#s100 .d-h{color:#FF00F5;text-shadow:2px 0 #00FFF3}
#s100 .d-p{color:#b8e9c3}
#s100 .d-btn{background:#39FF14;color:#000;border:2px solid #fff;border-radius:0;box-shadow:4px 4px 0 #FF00F5;font-weight:700;letter-spacing:.04em}
#s100 .d-btn:hover{transform:translate(2px,2px);box-shadow:2px 2px 0 #00FFF3}
#s100 .d-btn.ghost{background:#00FFF3;color:#000;box-shadow:4px 4px 0 #39FF14}
#s100 .d-input{background:#000;border:2px dotted #00FFF3;color:#39FF14}
#s100 .d-badge{background:#FF00F5;color:#fff;border-radius:0;font-weight:700}
#s100 .d-prog{background:#111;border:1px solid #fff;border-radius:0}#s100 .d-prog i{background:repeating-linear-gradient(90deg,#FF00F5 0 8px,#00FFF3 8px 16px,#39FF14 16px 24px)}
#s100 .d-card{background:#0a0a0a;border:2px dashed #39FF14;border-radius:0;transform:rotate(.4deg)}
